INSERT INTO faqs (question, answer, sort_order) VALUES
  ('Do I need to reserve a table?', 'Walk-ins are welcome, but we recommend reserving for groups and for Friday and weekend evenings.', 0),
  ('Do you deliver?', 'Yes, through our delivery partners and our own riders in nearby areas. Ask us on WhatsApp.', 1),
  ('How far ahead should I book catering?', 'Ideally 2 to 4 weeks for large events. For smaller orders, contact us and we''ll do our best.', 2),
  ('Can you cater for dietary needs?', 'Yes. Tell us about allergies or dietary needs when you reserve or request catering.', 3),
  ('Do you host private events?', 'Yes. Ask about our private room and party packages.', 4);
